/**
 * @file    Com_Types.h
 * @brief   Com configuration types (generated by dbc2c.py).
 */
#ifndef COM_TYPES_H
#define COM_TYPES_H

#include "ComStack_Types.h"

typedef uint16 Com_SignalIdType;

/** Application data type of a signal; dbc2c.py picks the smallest type that fits. */
typedef enum
{
    COM_BOOLEAN = 0,
    COM_UINT8,
    COM_UINT16,
    COM_UINT32,
    COM_SINT8,
    COM_SINT16,
    COM_SINT32
} Com_SignalTypeType;

typedef enum
{
    COM_LITTLE_ENDIAN = 0,  /* DBC "@1" (Intel) */
    COM_BIG_ENDIAN          /* DBC "@0" (Motorola) */
} Com_SignalEndiannessType;

typedef enum
{
    COM_RECEIVE = 0,
    COM_SEND
} Com_IPduDirectionType;

typedef struct
{
    /* Bit position as in DBC: LSB for little endian, MSB (sawtooth numbering)
     * for big endian. Note: AUTOSAR ComBitPosition uses the LSB for both. */
    uint8                    bitPosition;
    uint8                    bitSize;          /* 1..32 */
    Com_SignalEndiannessType endianness;
    Com_SignalTypeType       signalType;
    PduIdType                ipduId;           /* Owning Com I-PDU */
    uint32                   initValue;        /* Raw init value, packed at Com_Init */
} Com_SignalConfigType;

typedef struct
{
    Com_IPduDirectionType direction;
    PduLengthType         length;              /* Bytes, 0..8 */
    uint8                *buffer;              /* Generated static buffer of 'length' bytes */
    PduIdType             pduRTxPduId;         /* COM_SEND only: PduR_ComTransmit id */
} Com_IPduConfigType;

typedef struct
{
    const Com_SignalConfigType *signals;
    Com_SignalIdType            numSignals;
    const Com_IPduConfigType   *ipdus;
    PduIdType                   numIPdus;
} Com_ConfigType;

#endif /* COM_TYPES_H */
